mapper.select:
SELECT id, session_id, user_id, title, kb_id, created_at, updated_at
FROM chat_session
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit}

mapper.update:
UPDATE chat_session
SET title = COALESCE(#{title}, title), updated_at = NOW()
WHERE session_id = #{sessionId}

mapper.delete:
DELETE FROM chat_session
WHERE user_id = #{userId}
  AND session_id IN

    #{sessionId}
